import sys, zlib, re

path = sys.argv[1]
data = open(path, 'rb').read()

streams = []
for m in re.finditer(rb'stream\r?\n', data):
    start = m.end()
    end = data.find(b'endstream', start)
    if end == -1:
        continue
    raw = data[start:end]
    try:
        out = zlib.decompress(raw)
    except Exception:
        out = raw
    streams.append(out)

for i, t in enumerate(streams):
    s = t.decode('latin-1')
    if 'Tj' not in s and 'TJ' not in s:
        continue
    print('=== STREAM %d ===' % i)
    for line in s.splitlines():
        if '(' in line and (line.rstrip().endswith('Tj') or 'TJ' in line):
            parts = re.findall(r'\((?:\\.|[^\\()])*\)', line)
            txt = ''.join(p[1:-1] for p in parts)
            txt = txt.replace('\\(', '(').replace('\\)', ')').replace('\\\\', '\\')
            if txt.strip():
                print(txt)
